import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

const Analytics = () => {
  const [chartData, setChartData] = useState([]);

  useEffect(() => {
    fetchStats();
  }, []);

  async function fetchStats() {
    const { data } = await supabase.from("parking_slots").select("created_at");

    // Process data: Count cars per date
    const stats = {};
    data.forEach(entry => {
      const date = new Date(entry.created_at).toLocaleDateString();
      stats[date] = (stats[date] || 0) + 1;
    });

    // Convert to array for Recharts
    const formattedData = Object.keys(stats).map(date => ({
      date: date,
      cars: stats[date]
    })).slice(-7); // Last 7 days

    setChartData(formattedData);
  }

  return (
    <div className="dashboard-root">
      <h1>📊 Traffic Analytics</h1>
      <p style={{color:"gray", marginBottom:"30px"}}>Total vehicles entering per day (Last 7 Days)</p>

      <div className="summary-card" style={{height: "400px"}}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData}>
            <XAxis dataKey="date" />
            <YAxis />
            <Tooltip />
            <Bar dataKey="cars" fill="#3b82f6" name="Vehicles" radius={[5, 5, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Analytics;
